<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Sorting Visualizer</title>
  <style>
    :root {
      --bg: #0b0e14;
      --panel: #121722;
      --border: #243044;
      --text: #e6edf3;
      --muted: #8b9bb4;
      --accent: #3d8bfd;
      --bar: #4aa3ff;
      --bar-compare: #f5c542;
      --bar-swap: #ff6b6b;
      --bar-ok: #3dd68c;
      --btn: #1c2433;
      --btn-hover: #273247;
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body {
      height: 100%;
      background: var(--bg);
      color: var(--text);
      font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, sans-serif;
    }
    body {
      display: flex;
      flex-direction: column;
      min-height: 100%;
      padding: 20px;
      gap: 16px;
    }
    header {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
    }
    h1 {
      font-size: 1.15rem;
      font-weight: 600;
      letter-spacing: 0.02em;
    }
    h1 span { color: var(--muted); font-weight: 400; font-size: 0.85rem; margin-left: 8px; }
    .controls { display: flex; gap: 8px; flex-wrap: wrap; }
    button {
      background: var(--btn);
      color: var(--text);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 8px 16px;
      font-size: 0.9rem;
      cursor: pointer;
    }
    button:hover:not(:disabled) { background: var(--btn-hover); }
    button:disabled { opacity: 0.45; cursor: not-allowed; }
    #sort { background: #1a3a6b; border-color: #2d5aa0; }
    #sort:hover:not(:disabled) { background: #214781; }
    #stage {
      flex: 1;
      min-height: 280px;
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 16px 12px 8px;
      display: flex;
      flex-direction: column;
    }
    #bars {
      flex: 1;
      display: flex;
      align-items: flex-end;
      justify-content: center;
      gap: 2px;
      width: 100%;
      height: 100%;
      min-height: 240px;
    }
    .bar {
      flex: 1 1 0;
      min-width: 2px;
      max-width: 28px;
      background: linear-gradient(180deg, #79c0ff 0%, var(--bar) 100%);
      border-radius: 3px 3px 0 0;
      transition: height 80ms linear, background 80ms linear;
    }
    .bar.compare { background: var(--bar-compare); }
    .bar.swap { background: var(--bar-swap); }
    .bar.done { background: var(--bar-ok); }
    footer {
      color: var(--muted);
      font-size: 0.78rem;
    }
  </style>
</head>
<body>
  <header>
    <h1>Sorting Visualizer <span>bubble sort · ascending</span></h1>
    <div class="controls">
      <button id="sort" type="button">Sort</button>
      <button id="shuffle" type="button">Shuffle</button>
      <button id="reset" type="button">Reset</button>
    </div>
  </header>
  <div id="stage">
    <div id="bars"></div>
  </div>
  <footer>One comparison per step. Use Sort to animate, or drive via window.viz.</footer>
  <script>
    (function () {
      const DEFAULT = [64, 34, 25, 12, 22, 11, 90, 45, 78, 33, 18, 55, 41, 7, 88, 29, 61, 15, 73, 50];

      const state = {
        arr: DEFAULT.slice(),
        original: DEFAULT.slice(),
        i: 0,
        j: 0,
        swappedThisPass: false,
        finished: false,
        highlight: [],
        highlightKind: "",
        animating: false,
        timer: null
      };

      const barsEl = document.getElementById("bars");
      const sortBtn = document.getElementById("sort");
      const shuffleBtn = document.getElementById("shuffle");
      const resetBtn = document.getElementById("reset");

      function isAscending(a) {
        for (let k = 1; k < a.length; k++) {
          if (a[k - 1] > a[k]) return false;
        }
        return true;
      }

      function resetAlgo() {
        state.i = 0;
        state.j = 0;
        state.swappedThisPass = false;
        state.finished = isAscending(state.arr);
        state.highlight = [];
        state.highlightKind = "";
      }

      function stopAnim() {
        if (state.timer != null) {
          clearTimeout(state.timer);
          state.timer = null;
        }
        state.animating = false;
        sortBtn.disabled = false;
        shuffleBtn.disabled = false;
        resetBtn.disabled = false;
      }

      function render() {
        const a = state.arr;
        const n = a.length;
        const max = n ? Math.max.apply(null, a.concat([1])) : 1;
        const fully = state.finished || isAscending(a);
        barsEl.innerHTML = "";
        for (let k = 0; k < n; k++) {
          const el = document.createElement("div");
          el.className = "bar";
          const pct = (Number(a[k]) / max) * 100;
          el.style.height = Math.max(2, pct) + "%";
          if (fully) {
            el.classList.add("done");
          } else if (state.highlight.indexOf(k) !== -1) {
            el.classList.add(state.highlightKind === "swap" ? "swap" : "compare");
          }
          barsEl.appendChild(el);
        }
      }

      function setArray(input) {
        const next = Array.prototype.slice.call(input || []).map(Number);
        state.arr = next;
        state.original = next.slice();
        stopAnim();
        resetAlgo();
        render();
      }

      function shuffleInPlace(a) {
        for (let i = a.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          const t = a[i];
          a[i] = a[j];
          a[j] = t;
        }
      }

      function sortStep() {
        const a = state.arr;
        const n = a.length;

        if (n <= 1 || isAscending(a)) {
          state.finished = true;
          state.highlight = [];
          state.highlightKind = "";
          render();
          return true;
        }

        state.finished = false;

        if (state.i >= n - 1) {
          state.i = 0;
          state.j = 0;
          state.swappedThisPass = false;
        }

        const j = state.j;
        const left = a[j];
        const right = a[j + 1];
        let didSwap = false;

        if (left > right) {
          a[j] = right;
          a[j + 1] = left;
          didSwap = true;
          state.swappedThisPass = true;
        }

        state.highlight = [j, j + 1];
        state.highlightKind = didSwap ? "swap" : "compare";

        state.j += 1;
        if (state.j >= n - 1 - state.i) {
          state.j = 0;
          state.i += 1;
          if (!state.swappedThisPass) {
            state.finished = true;
          }
          state.swappedThisPass = false;
        }

        const done = state.finished || isAscending(a);
        if (done) {
          state.finished = true;
          state.highlight = [];
          state.highlightKind = "";
        }
        render();
        return done;
      }

      function animateSort() {
        if (state.animating) return;
        if (isAscending(state.arr)) {
          state.finished = true;
          render();
          return;
        }
        state.animating = true;
        sortBtn.disabled = true;
        shuffleBtn.disabled = true;
        resetBtn.disabled = true;

        function tick() {
          const done = sortStep();
          if (done) {
            stopAnim();
            return;
          }
          state.timer = setTimeout(tick, 40);
        }
        tick();
      }

      sortBtn.addEventListener("click", animateSort);
      shuffleBtn.addEventListener("click", function () {
        stopAnim();
        shuffleInPlace(state.arr);
        resetAlgo();
        render();
      });
      resetBtn.addEventListener("click", function () {
        stopAnim();
        state.arr = state.original.slice();
        resetAlgo();
        render();
      });

      window.viz = {
        array: function () { return state.arr.slice(); },
        setArray: setArray,
        sortStep: sortStep,
        sorted: function () { return isAscending(state.arr); }
      };

      resetAlgo();
      render();
    })();
  </script>
</body>
</html>
